<template>
  <section class="layout flex flex-col min-h-screen w-full bg-accent">
    <div id="safe-area-top" />
    <OfflineBanner />
    <Card class="w-full rounded-t-none shadow-xl">
      <div
        class="flex flex-row flex-wrap gap-2 justify-between items-center max-w-screen-2xl mx-auto p-2 sm:p-4 lg:px-8"
      >
        <NuxtLink to="/">
          <Logo class="text-logo h-full w-full max-w-[155px] py-2" />
        </NuxtLink>
        <div class="flex items-center gap-2">
          <NuxtLink v-if="isAuthenticated" :to="{ name: 'applications' }">
            <Button class="float-right" variant="outline">Upcoming Projects</Button>
          </NuxtLink>
          <template v-else>
            <NuxtLink :to="{ name: 'login' }">
              <Button class="float-right" variant="outline">Log In</Button>
            </NuxtLink>
            <NuxtLink v-if="!isSubcontractorPublic" :to="{ name: 'sign-up' }">
              <Button class="float-right">Sign Up</Button>
            </NuxtLink>
          </template>
        </div>
      </div>
    </Card>
    <div :id="PTR_CONTENT_ID" class="flex-1 min-h-0 flex flex-col overflow-hidden">
      <section class="flex-grow w-full max-w-screen-2xl mx-auto p-2 sm:p-4 lg:p-8 pb-28 pt-12">
        <slot />
      </section>
      <footer class="w-full max-w-screen-2xl mx-auto px-4 py-3 text-center text-xs text-muted-foreground">
        <span>v{{ version }}</span>
        <span class="mx-1">&middot;</span>
        <span>&copy; {{ new Date().getFullYear() }} Patriot Grassroots. All rights reserved.</span>
      </footer>
      <div id="safe-area-bottom" />
    </div>
  </section>
</template>

<script setup lang="ts">
import { Logo } from '~/assets/icons';
import * as Sentry from '@sentry/nuxt';
import { SplashScreen } from '@capacitor/splash-screen';
import { SafeArea } from '@capacitor-community/safe-area';
import { PTR_CONTENT_ID } from '~/plugins/pullToRefresh';

const { isAuthenticated } = useUserRole();
const route = useRoute();
const isSubcontractorPublic = computed(() => Boolean(route.meta.subcontractorPublic));
const version = useRuntimeConfig().public.version;

const feedback = Sentry.getFeedback();
let widget: any | null = null;

onMounted(async () => {
  await SplashScreen.hide();
  setTimeout(async () => {
    await SafeArea.enable({
      config: {
        customColorsForSystemBars: true,
        statusBarContent: 'dark',
        navigationBarContent: 'dark',
      },
    });
  }, 250);
  widget = feedback?.createWidget();
});

onBeforeUnmount(() => {
  widget?.removeFromDom();
});
</script>
